const statusClasses = { active: "bg-green-100 text-green-900", inactive: "bg-slate-200 text-slate-900", graduated: "bg-indigo-100 text-indigo-900" };
function StudentStatus({ status }) { const safe = Object.hasOwn(statusClasses, status) ? status : "inactive"; return <span className={"rounded-full px-3 py-1 " + statusClasses[safe]}>{safe}</span>; }
