let students=[{id:1,name:'Maria Santos',course:'IT',grade:91},{id:2,name:'Joel Cruz',course:'CS',grade:72},{id:3,name:'Ana Reyes',course:'IT',grade:85}];
let editing=null,deleting=null,page=1;const pageSize=2;
const byId=id=>document.getElementById(id);
const notify=text=>{byId('statusMessage').textContent=text;};
const open=(type,id)=>({show:()=>{byId(id).hidden=false;},hide:()=>{byId(id).hidden=true;}});
function render(){
 const search=byId('studentSearch').value.trim().toLowerCase(),course=byId('courseFilter').value;
 const result=students.filter(s=>s.name.toLowerCase().includes(search)&&(!course||s.course===course)).sort((a,b)=>byId('sortOrder').value==='grade'?b.grade-a.grade:a.name.localeCompare(b.name));
 const pages=Math.max(1,Math.ceil(result.length/pageSize));page=Math.min(Math.max(page,1),pages);const visible=result.slice((page-1)*pageSize,page*pageSize);
 byId('studentRows').replaceChildren();byId('studentCards').replaceChildren();
 byId('studentCount').textContent=String(students.length);byId('passingCount').textContent=String(students.filter(s=>s.grade>=75).length);
 byId('listStatus').textContent=result.length?result.length+' matching fictional records':'No students match. Try another search/filter.';
 byId('pageLabel').textContent='Page '+page+' of '+pages;byId('previousPage').disabled=page<=1;byId('nextPage').disabled=page>=pages;
 for(const s of visible){
  const row=document.createElement('tr');for(const value of [s.id,s.name,s.course,s.grade,s.grade>=75?'Passed':'Needs support']){const cell=document.createElement('td');cell.textContent=String(value);cell.className='border-b border-slate-300 p-3 dark:border-slate-600';if(value==='Passed')cell.className+=' bg-green-100 font-semibold text-green-900';if(value==='Needs support')cell.className+=' bg-amber-100 font-semibold text-amber-950';row.append(cell);}
  const actions=document.createElement('td');for(const [label,handler] of [['Details',()=>{byId('detailContent').textContent=s.name+' · '+s.course+' · grade '+s.grade;open('Modal','detailModal').show();}],['Edit',()=>{editing=s.id;byId('recordName').value=s.name;byId('recordCourse').value=s.course;byId('recordGrade').value=String(s.grade);byId('recordError').textContent='';open('Modal','studentModal').show();}],['Delete',()=>{deleting=s.id;byId('deleteText').textContent='Delete fictional record '+s.name+'?';open('Modal','deleteModal').show();}]]){const button=document.createElement('button');button.type='button';button.className='rounded-lg bg-indigo-700 px-4 py-2 font-semibold text-white transition-colors hover:bg-indigo-800 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-indigo-700 disabled:opacity-50 m-1 text-sm';button.textContent=label;button.addEventListener('click',handler);actions.append(button);}row.append(actions);byId('studentRows').append(row);
  const column=document.createElement('div');column.className='min-w-0';const card=document.createElement('article');card.className='rounded-xl border border-slate-300 bg-white p-5 shadow-sm dark:border-slate-600 dark:bg-slate-800';const heading=document.createElement('h3');heading.className='text-lg font-semibold';heading.textContent=s.name;const text=document.createElement('p');text.textContent=s.course+' · '+s.grade;card.append(heading,text);column.append(card);byId('studentCards').append(column);
 }
}
byId('studentSearch').addEventListener('input',()=>{page=1;render();});for(const id of ['courseFilter','sortOrder'])byId(id).addEventListener('change',()=>{page=1;render();});
byId('previousPage').addEventListener('click',()=>{page--;render();});byId('nextPage').addEventListener('click',()=>{page++;render();});
byId('addStudentButton').addEventListener('click',()=>{editing=null;byId('recordName').value='';byId('recordCourse').value='IT';byId('recordGrade').value='';byId('recordError').textContent='';open('Modal','studentModal').show();});
byId('studentForm').addEventListener('submit',event=>{event.preventDefault();const name=byId('recordName').value.trim(),course=byId('recordCourse').value,raw=byId('recordGrade').value.trim(),grade=Number(raw);if(!name||name.length>100||!['IT','CS'].includes(course)||!raw||!Number.isFinite(grade)||grade<0||grade>100){byId('recordError').textContent='Enter a name, IT/CS course and grade from 0 to 100.';return;}if(editing!==null)students=students.map(s=>s.id===editing?{...s,name,course,grade}:s);else{if(students.length>=100){byId('recordError').textContent='Practice limit: 100 records.';return;}students.push({id:Math.max(0,...students.map(s=>s.id))+1,name,course,grade});}open('Modal','studentModal').hide();render();notify('Practice record updated in memory only.');});
byId('confirmDelete').addEventListener('click',()=>{students=students.filter(s=>s.id!==deleting);deleting=null;open('Modal','deleteModal').hide();render();notify('Practice record deleted from memory only.');});
byId('demoLogin')?.addEventListener('submit',event=>{event.preventDefault();const entered=byId('demoUser').value.trim()&&byId('demoPassword').value;byId('demoPassword').value='';byId('loginFeedback').textContent=entered?'Login UI preview only. No user is authenticated.':'Enter fictional values to preview the form; no credentials are verified.';});
render();console.log('Fictional UI ready. All changes reset on Run.');
const menu=document.getElementById('mobileLinks'),toggle=document.getElementById('menuToggle');toggle.addEventListener('click',()=>{const expanded=toggle.getAttribute('aria-expanded')==='true';toggle.setAttribute('aria-expanded',String(!expanded));menu.classList.toggle('hidden',expanded);});
const themeRoot=document.getElementById('themeRoot'),themeToggle=document.getElementById('themeToggle');themeToggle.addEventListener('click',()=>{const dark=themeRoot.classList.toggle('dark');themeToggle.setAttribute('aria-pressed',String(dark));localStorage.setItem('practice-theme',dark?'dark':'light');});
for(const close of document.querySelectorAll('[data-close]'))close.addEventListener('click',()=>{document.getElementById(close.getAttribute('data-close')).hidden=true;});
document.body.addEventListener('keydown',e=>{if(e.key==='Escape')for(const dialog of document.querySelectorAll('[role="dialog"]'))dialog.hidden=true;});
byId('simulateLoading').addEventListener('click',()=>{byId('listStatus').textContent='Loading fictional records…';setTimeout(render,500);});
